			sb.Write(buf[:n])
		}
		if err != nil {
			break
		}
	}
	tokens := strings.Fields(sb.String())
	i := 0
	n, _ := strconv.Atoi(tokens[i]); i++
	nums := make([]int, n); for j := 0; j < n; j++ { nums[j], _ = strconv.Atoi(tokens[i]); i++ }
	target, _ := strconv.Atoi(tokens[i]); i++
	ans := twoSum(nums, target)
	strs := make([]string, len(ans))
	for idx, v := range ans {
		strs[idx] = fmt.Sprint(v)
	}
	fmt.Println(strings.Join(strs, " "))
}

